K:=Kernel(Transpose(B)); w:=Basis(K)[1]; if w[1] lt 0 then w:=-w; end if; assert Min(Eltseq(w)) eq 1;
B:=B*DiagonalMatrix(Eltseq(w)); m:=Ncols(B); V:=RSpace(Integers(),m); tested:=0;
base:=HorizontalJoin(2*B,ZeroMatrix(Integers(),Nrows(B),1));
seen:={}; pairs:=0; scale:=9;
function trans(i,a)
 x:=(a*(i-1)) mod n;return Min(x,n-x)+1;
end function;
un:=[a:a in [1..n] | GCD(a,n) eq 1]; L:=Lattice(B);
for a in un do
 M:=Matrix(Integers(),[[B[k,trans(j,a)]:j in [1..m]]:k in [1..Nrows(B)]]);
 assert L eq Lattice(M);
end for;
for i in [1..m] do for j in [i+1..m] do
 if {i,j} in seen then continue; end if; pairs+:=1;
 seen join:={{trans(i,a),trans(j,a)}:a in un};
 center:=d*(V.i-V.j);
 row:=Matrix(Integers(),1,m+1,Eltseq(-center) cat [scale]);
 A:=Lattice(VerticalJoin(base,row));
 for pair in ShortVectors(A,2*d^2+scale^2:Proof:=true) do
  v:=pair[1]; t:=Integers()!(v[m+1]/scale);
  if Abs(t) eq 1 then
   w:=V![t*v[a]+center[a]:a in [1..m]];
   if not IsZero(w) then assert &+[Abs(z):z in Eltseq(w)] gt 4*d; tested+:=1; end if;
  end if;
 end for;
printf "pair %o/%o, candidates %o\n",i,j,tested;
end for;end for;
assert #seen eq Binomial(m,2);
print "EXACT_PASS",n,d,tested;quit;
